// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testRegression_property() public {
        address alice = address(0x1234);
        vm.deal(alice, 1 ether);
        vm.prank(alice);
        (bool ok1,) = address(c).call{value: 1 wei}("");
        assertTrue(ok1);

        address target = address(0x5678);
        c.sendMoney(target, 0);

        assertTrue(c.depositsCount() == 1);
    }
}
